17	{
18	  int fd;
19	  int ret;
20	  struct rtc_time rtctime;
21	  struct tm tm_buf;
22	  time_t t;
23	  char timebuf[64];
24	
25	  printf("[RTC] Testing RTC...\n");
26	
27	  fd = open("/dev/rtc0", O_RDWR);
28	  if (fd < 0)
29	    {
30	      printf("[RTC] ERROR: Failed to open /dev/rtc0: %d\n", errno);
31	      return -errno;
32	    }
33	
34	  ret = ioctl(fd, RTC_RD_TIME, (unsigned long)(uintptr_t)&rtctime);
35	  if (ret < 0)
36	    {
37	      printf("[RTC] ERROR: RTC_RD_TIME failed: %d\n", errno);
38	      close(fd);
39	      return -errno;
40	    }
41	
42	  printf("[RTC] Current RTC time: %04d-%02d-%02d %02d:%02d:%02d\n",
43	         rtctime.tm_year + 1900, rtctime.tm_mon + 1, rtctime.tm_mday,
44	         rtctime.tm_hour, rtctime.tm_min, rtctime.tm_sec);
45	
46	  memset(&tm_buf, 0, sizeof(tm_buf));
47	  tm_buf.tm_sec   = rtctime.tm_sec;
48	  tm_buf.tm_min   = rtctime.tm_min;
49	  tm_buf.tm_hour  = rtctime.tm_hour;
50	  tm_buf.tm_mday  = rtctime.tm_mday;
51	  tm_buf.tm_mon   = rtctime.tm_mon;
52	  tm_buf.tm_year  = rtctime.tm_year;
53	  tm_buf.tm_isdst = -1;
54	
55	  t = mktime(&tm_buf);
56	  if (t != (time_t)-1)
57	    {
58	      struct tm *tmp = localtime(&t);
59	      if (tmp)
60	        {
61	          strftime(timebuf, sizeof(timebuf), "%Y-%m-%d %H:%M:%S %A", tmp);
62	          printf("[RTC] Formatted time: %s\n", timebuf);
63	        }
64	    }
65	
66	  printf("[RTC] Setting time to 2025-01-01 12:00:00...\n");
67	
68	  memset(&rtctime, 0, sizeof(rtctime));
69	  rtctime.tm_year = 2025 - 1900;
70	  rtctime.tm_mon  = 1 - 1;
71	  rtctime.tm_mday = 1;
72	  rtctime.tm_hour = 12;
73	  rtctime.tm_min  = 0;
74	  rtctime.tm_sec  = 0;
75	
76	  ret = ioctl(fd, RTC_SET_TIME, (unsigned long)(uintptr_t)&rtctime);
77	  if (ret < 0)
78	    {
79	      printf("[RTC] ERROR: RTC_SET_TIME failed: %d\n", errno);
80	      close(fd);
81	      return -errno;
82	    }
83	
84	  printf("[RTC] Time set successfully\n");
85	
86	  up_mdelay(2000);
87	
88	  ret = ioctl(fd, RTC_RD_TIME, (unsigned long)(uintptr_t)&rtctime);
89	  if (ret < 0)
90	    {
91	      printf("[RTC] ERROR: RTC_RD_TIME after set failed: %d\n", errno);
92	      close(fd);
93	      return -errno;
94	    }
95	
96	  printf("[RTC] RTC time after 2s: %04d-%02d-%02d %02d:%02d:%02d\n",
97	         rtctime.tm_year + 1900, rtctime.tm_mon + 1, rtctime.tm_mday,
98	         rtctime.tm_hour, rtctime.tm_min, rtctime.tm_sec);
99	
100	  if (rtctime.tm_year + 1900 == 2025 &&
101	      rtctime.tm_mon + 1 == 1 &&
102	      rtctime.tm_mday == 1 &&
103	      rtctime.tm_hour == 12 &&
104	      rtctime.tm_min == 0 &&
105	      rtctime.tm_sec >= 2 && rtctime.tm_sec <= 3)
106	    {
107	      printf("[RTC] Time verification PASSED\n");
108	    }
109	  else
110	    {
111	      printf("[RTC] WARNING: Time verification unexpected, RTC may not be running\n");
112	    }
113	
114	  close(fd);
115	  printf("[RTC] Done.\n\n");
116	  return OK;
117	}
