40	static int ls2k0300_rtc_rdtime(FAR struct rtc_lowerhalf_s *lower,
41	                              FAR struct rtc_time *rtctime)
42	{
43	  FAR struct ls2k0300_rtc_lowerhalf_s *priv =
44	      (FAR struct ls2k0300_rtc_lowerhalf_s *)lower;
45	  uint32_t toy_read0;
46	  uint32_t toy_read1;
47	  irqstate_t flags;
48	
49	  memset(rtctime, 0, sizeof(struct rtc_time));
50	
51	  flags = enter_critical_section();
52	
53	  toy_read1 = rtc_getreg(priv, LS2K0300_RTC_TOY_READ1_REG);
54	  toy_read0 = rtc_getreg(priv, LS2K0300_RTC_TOY_READ0_REG);
55	
56	  leave_critical_section(flags);
57	
58	  rtctime->tm_sec  = (toy_read0 >> RTC_TOY_SEC_SHIFT) & RTC_TOY_SEC_MASK;
59	  rtctime->tm_min  = (toy_read0 >> RTC_TOY_MIN_SHIFT) & RTC_TOY_MIN_MASK;
60	  rtctime->tm_hour = (toy_read0 >> RTC_TOY_HOUR_SHIFT) & RTC_TOY_HOUR_MASK;
61	  rtctime->tm_mday = (toy_read0 >> RTC_TOY_DAY_SHIFT) & RTC_TOY_DAY_MASK;
62	  rtctime->tm_mon  = ((toy_read0 >> RTC_TOY_MON_SHIFT) & RTC_TOY_MON_MASK) - 1;
63	  rtctime->tm_year = toy_read1;
64	
65	  if (rtctime->tm_mon < 0 || rtctime->tm_mon > 11 ||
66	      rtctime->tm_mday < 1 || rtctime->tm_mday > 31 ||
67	      rtctime->tm_hour > 23 || rtctime->tm_min > 59 ||
68	      rtctime->tm_sec > 61)
69	    {
70	      rtctime->tm_sec  = 0;
71	      rtctime->tm_min  = 0;
72	      rtctime->tm_hour = 0;
73	      rtctime->tm_mday = 1;
74	      rtctime->tm_mon  = 0;
75	      rtctime->tm_year = 0;
76	    }
77	
78	  rtctime->tm_wday  = -1;
79	  rtctime->tm_yday  = -1;
80	  rtctime->tm_isdst = -1;
81	#ifdef CONFIG_RTC_HIRES
82	  rtctime->tm_nsec  = 0;
83	#endif
84	
85	  return OK;
86	}
