88	static int ls2k0300_rtc_settime(FAR struct rtc_lowerhalf_s *lower,
89	                               FAR const struct rtc_time *rtctime)
90	{
91	  FAR struct ls2k0300_rtc_lowerhalf_s *priv =
92	      (FAR struct ls2k0300_rtc_lowerhalf_s *)lower;
93	  uint32_t toy_write0;
94	  irqstate_t flags;
95	
96	  toy_write0  = (rtctime->tm_sec << RTC_TOY_SEC_SHIFT);
97	  toy_write0 |= (rtctime->tm_min << RTC_TOY_MIN_SHIFT);
98	  toy_write0 |= (rtctime->tm_hour << RTC_TOY_HOUR_SHIFT);
99	  toy_write0 |= (rtctime->tm_mday << RTC_TOY_DAY_SHIFT);
100	  toy_write0 |= ((rtctime->tm_mon + 1) << RTC_TOY_MON_SHIFT);
101	
102	  flags = enter_critical_section();
103	
104	  rtc_putreg(priv, LS2K0300_RTC_TOY_WRITE0_REG, toy_write0);
105	  rtc_putreg(priv, LS2K0300_RTC_TOY_WRITE1_REG, (uint32_t)rtctime->tm_year);
106	
107	  leave_critical_section(flags);
108	
109	  priv->haveset = true;
110	
111	  return OK;
112	}
