99	static inline int date_showtime(FAR struct nsh_vtbl_s *vtbl,
100	                                FAR const char *name, bool utc,
101	                                FAR const char *format)
102	{
103	  struct timespec ts;
104	  struct tm tm;
105	  char timbuf[MAX_TIME_STRING];
106	  int ret;
107	
108	  /* Get the current time */
109	
110	  ret = clock_gettime(CLOCK_REALTIME, &ts);
111	  if (ret < 0)
112	    {
113	      nsh_error(vtbl, g_fmtcmdfailed, name, "clock_gettime", NSH_ERRNO);
114	      return ERROR;
115	    }
116	
117	  /* Break the current time up into the format needed by strftime */
118	
119	  if (utc)
120	    {
121	      if (gmtime_r((FAR const time_t *)&ts.tv_sec, &tm) == NULL)
122	        {
123	          nsh_error(vtbl, g_fmtcmdfailed, name, "gmtime_r", NSH_ERRNO);
124	          return ERROR;
125	        }
126	    }
127	  else
128	    {
129	      if (localtime_r((FAR const time_t *)&ts.tv_sec, &tm) == NULL)
130	        {
131	          nsh_error(vtbl, g_fmtcmdfailed, name, "localtime_r", NSH_ERRNO);
132	          return ERROR;
133	        }
134	    }
135	
136	  /* Show the current time in the requested format */
137	
138	  ret = strftime(timbuf, MAX_TIME_STRING, format, &tm);
139	  if (ret < 0)
140	    {
141	      nsh_error(vtbl, g_fmtcmdfailed, name, "strftime", NSH_ERRNO);
142	      return ERROR;
143	    }
144	
145	  nsh_output(vtbl, "%s\n", timbuf);
146	  return OK;
147	}
148	#endif
