155	static inline int date_settime(FAR struct nsh_vtbl_s *vtbl,
156	                               FAR const char *name, bool utc,
157	                               FAR char *newtime)
158	{
159	  struct timespec ts;
160	  struct tm tm;
161	  FAR char *token;
162	  FAR char *saveptr;
163	  long result;
164	  int ret;
165	
166	  memset(&tm, 0, sizeof(tm));
167	
168	  /* Only this date format is supported: MMM DD HH:MM:SS YYYY */
169	
170	  /* Get the month abbreviation */
171	
172	  token = strtok_r(newtime, " \t", &saveptr);
173	  if (token == NULL)
174	    {
175	      goto errout_bad_parm;
176	    }
177	
178	  tm.tm_mon = date_month(token);
179	  if (tm.tm_mon < 0)
180	    {
181	      goto errout_bad_parm;
182	    }
183	
184	  /* Get the day of the month.
185	   * NOTE: Accepts day-of-month up to 31 for all months
186	   */
187	
188	  token = strtok_r(NULL, " \t", &saveptr);
189	  if (token == NULL)
190	    {
191	      goto errout_bad_parm;
192	    }
193	
194	  result = strtol(token, NULL, 10);
195	  if (result < 1 || result > 31)
196	    {
197	      goto errout_bad_parm;
198	    }
199	
200	  tm.tm_mday = (int)result;
201	
202	  /* Get the hours */
203	
204	  token = strtok_r(NULL, " \t:", &saveptr);
205	  if (token == NULL)
206	    {
207	      goto errout_bad_parm;
208	    }
209	
210	  result = strtol(token, NULL, 10);
211	  if (result < 0 || result > 23)
212	    {
213	      goto errout_bad_parm;
214	    }
215	
216	  tm.tm_hour = (int)result;
217	
218	  /* Get the minutes */
219	
220	  token = strtok_r(NULL, " \t:", &saveptr);
221	  if (token == NULL)
222	    {
223	      goto errout_bad_parm;
224	    }

240	    }
241	
242	  result = strtol(token, NULL, 10);
243	  if (result < 0 || result > 61)
244	    {
245	      goto errout_bad_parm;
246	    }
247	
248	  tm.tm_sec = (int)result;
249	
250	  /* And finally the year */
251	
252	  token = strtok_r(NULL, " \t", &saveptr);
253	  if (token == NULL)
254	    {
255	      goto errout_bad_parm;
256	    }
257	
258	  result = strtol(token, NULL, 10);
259	  if (result < 1900 || result > 2100)
260	    {
261	      goto errout_bad_parm;
262	    }
263	
264	  tm.tm_year = (int)result - 1900;
265	
266	  /* Convert this to the right form, then set the timer */
267	
268	  ts.tv_sec  = utc ? timegm(&tm): mktime(&tm);
269	  ts.tv_nsec = 0;
270	
271	  ret = clock_settime(CLOCK_REALTIME, &ts);
272	  if (ret < 0)
273	    {
274	      nsh_error(vtbl, g_fmtcmdfailed, name, "clock_settime", NSH_ERRNO);
275	      return ERROR;
276	    }
277	
278	  return OK;
279	
280	errout_bad_parm:
281	  nsh_error(vtbl, g_fmtarginvalid, name);
282	  return ERROR;
283	}
