```c
#include <arch/csr.h>
#include <nuttx/clock.h>
#include <syslog.h>

/* Calibrate the constant-timer (CSR.TCFG) frequency by counting
 * stable-counter (rdtime) ticks during one RTC second.  On the 2K0300 the
 * architectural CPUCFG4 path reports the wrong frequency, so the tick must
 * be measured against the battery-backed 32.768 kHz RTC.
 *
 * Returns the measured frequency in Hz, or 0 on failure (RTC not ticking).
 */
static uint64_t ls2k0300_calibrate_const_freq(
    FAR struct ls2k0300_rtc_lowerhalf_s *priv)
{
  uint32_t toy;
  uint32_t sec;
  uint32_t prev;
  uint64_t t0;
  uint64_t t1;
  uint32_t i;

  /* Snapshot the current RTC second. */

  toy  = rtc_getreg(priv, LS2K0300_RTC_TOY_READ0_REG);
  prev = (toy >> RTC_TOY_SEC_SHIFT) & RTC_TOY_SEC_MASK;

  /* Wait for the second to roll over (up to ~1.5s of polling). */

  for (i = 0; i < 5000000; i++)
    {
      toy = rtc_getreg(priv, LS2K0300_RTC_TOY_READ0_REG);
      sec = (toy >> RTC_TOY_SEC_SHIFT) & RTC_TOY_SEC_MASK;
      if (sec != prev)
        {
          break;
        }
    }

  if (sec == prev)
    {
      return 0;  /* RTC not ticking - caller keeps the default */
    }

  /* Measure stable-counter ticks for one full RTC second. */

  t0 = drdtime();
  prev = sec;

  for (i = 0; i < 5000000; i++)
    {
      toy = rtc_getreg(priv, LS2K0300_RTC_TOY_READ0_REG);
      sec = (toy >> RTC_TOY_SEC_SHIFT) & RTC_TOY_SEC_MASK;
      if (sec != prev)
        {
          break;
        }
    }

  t1 = drdtime();

  if (t1 <= t0)
    {
      return 0;
    }

  return t1 - t0;
}
```

Then in `ls2k0300_rtc_initialize`, after `rtc_initialize(0, lower)`:
```c
  /* Calibrate the system tick against the RTC and reprogram the constant
   * timer if a valid measurement was obtained.  This runs inside
   * clock_initialize() after up_timer_initialize() and before
   * clock_inittime(), so the corrected tick takes effect before the wall
   * clock is seeded from the RTC.
   */

  {
    uint64_t measured = ls2k0300_calibrate_const_freq(&g_rtc_lowerhalf);
    if (measured >= 100000ULL && measured <= 1000000000ULL)
      {
        uint64_t tval = measured / TICK_PER_SEC;
        uint64_t tcfg = tval << CSR_TCFG_VAL_SHIFT;
        tcfg |= CSR_TCFG_PERIOD | CSR_TCFG_EN;
        csr_writeq(tcfg, LOONGARCH_CSR_TCFG);
        syslog(LOG_INFO,
               "ls2k0300: const_timer calibrated to %llu Hz\n",
               (unsigned long long)measured);
      }
    else
      {
        syslog(LOG_INFO,
               "ls2k0300: const_timer calibration failed (%llu), "
               "keeping default\n", (unsigned long long)measured);
      }
  }
