static void ls2k0300_rtc_hw_init(FAR struct ls2k0300_rtc_lowerhalf_s *priv)
{
  uint32_t ctrl;

  rtc_putreg(priv, LS2K0300_RTC_TOY_TRIM_REG, 0x0);
  rtc_putreg(priv, LS2K0300_RTC_TRIM_REG, 0x0);

  ctrl = rtc_getreg(priv, LS2K0300_RTC_CTRL_REG);
  ctrl |= RTC_CTRL_TOY_ENABLE_BIT | RTC_CTRL_OSC_ENABLE_BIT;
  rtc_putreg(priv, LS2K0300_RTC_CTRL_REG, ctrl);
}

/* Upper bound on the number of polling iterations used while waiting for an
 * RTC second boundary.  This is only a safety cap so a board whose RTC
 * oscillator is not running cannot hang the boot; on a working RTC the
 * boundary is detected in well under one second of real time.
 */
#define RTC_SEC_POLL_MAX  20000000

/* Calibrate the constant-timer (CSR.TCFG) frequency by counting stable-
 * counter (rdtime) ticks during exactly one RTC second.
 *
 * On the 2K0300 the architectural CPUCFG4/CPUCFG5 path used by
 * ls2k0300_timerisr.c reports a constant-timer frequency that is roughly
 * 3x too high, which makes the periodic system tick fire too rarely and
 * the wall clock (CLOCK_REALTIME / `date`) drift ~3x slow.  The RTC is
 * driven by an independent 32.768 kHz crystal and keeps correct time, so
 * it is the right reference to measure the true constant-timer rate.
 *
 * This must run after the RTC oscillator has been enabled (i.e. after
 * ls2k0300_rtc_hw_init) and before the wall clock is seeded from the RTC.
 *
 * Returns the measured frequency in Hz, or 0 if the RTC was not ticking.
 */
static uint64_t ls2k0300_calibrate_const_freq(
    FAR struct ls2k0300_rtc_lowerhalf_s *priv)
{
  uint32_t toy;
  uint32_t prev;
  uint32_t now;
  uint32_t i;
  uint64_t t0;
  uint64_t t1;

  /* Snapshot the current RTC seconds field. */

  toy  = rtc_getreg(priv, LS2K0300_RTC_TOY_READ0_REG);
  prev = (toy >> RTC_TOY_SEC_SHIFT) & RTC_TOY_SEC_MASK;

  /* Wait for the seconds field to change once (catches a boundary). */

  for (i = 0; i < RTC_SEC_POLL_MAX; i++)
    {
      toy = rtc_getreg(priv, LS2K0300_RTC_TOY_READ0_REG);
      now = (toy >> RTC_TOY_SEC_SHIFT) & RTC_TOY_SEC_MASK;
      if (now != prev)
        {
          break;
        }
    }

  if (now == prev)
    {
      return 0;  /* RTC not ticking */
    }

  /* Measure stable-counter ticks across one full RTC second. */

  t0  = drdtime();
  prev = now;

  for (i = 0; i < RTC_SEC_POLL_MAX; i++)
    {
      toy = rtc_getreg(priv, LS2K0300_RTC_TOY_READ0_REG);
      now = (toy >> RTC_TOY_SEC_SHIFT) & RTC_TOY_SEC_MASK;
      if (now != prev)
        {
          break;
        }
    }

  t1 = drdtime();

  if (now == prev || t1 <= t0)
    {
      return 0;
    }

  return t1 - t0;
}

/* Reprogram the constant timer (CSR.TCFG) for the given frequency. */
static void ls2k0300_reprogram_const_timer(uint64_t freq)
{
  uint64_t tval;
  uint64_t tcfg;

  tval = freq / TICK_PER_SEC;
  tcfg  = tval << CSR_TCFG_VAL_SHIFT;
  tcfg |= CSR_TCFG_PERIOD | CSR_TCFG_EN;
  csr_writeq(tcfg, LOONGARCH_CSR_TCFG);
}

int ls2k0300_rtc_initialize(void)
{
  FAR struct rtc_lowerhalf_s *lower;
  uint64_t measured;
  int ret;

  ls2k0300_rtc_hw_init(&g_rtc_lowerhalf);

  lower = (FAR struct rtc_lowerhalf_s *)&g_rtc_lowerhalf;
  up_rtc_set_lowerhalf(lower, true);

  ret = rtc_initialize(0, lower);
  if (ret < 0)
    {
      rtcerr("ERROR: rtc_initialize failed: %d\n", ret);
      return ret;
    }

  /* Calibrate the system tick against the RTC and reprogram the constant
   * timer.  clock_initialize() calls up_rtc_initialize() (-> this function)
   * after up_timer_initialize() and before clock_inittime(), so the
   * corrected tick is in effect before the wall clock is seeded from the
   * RTC, and clock_inittime() self-corrects for whatever systicks already
   * accumulated.  Only apply the measured value if it is sane.
   */

  measured = ls2k0300_calibrate_const_freq(&g_rtc_lowerhalf);
  if (measured >= 1000000ULL && measured <= 1000000000ULL)
    {
      ls2k0300_reprogram_const_timer(measured);
      syslog(LOG_INFO,
             "ls2k0300: const_timer calibrated to %llu Hz "
             "(tval=%llu)\n",
             (unsigned long long)measured,
             (unsigned long long)(measured / TICK_PER_SEC));
    }
  else
    {
      syslog(LOG_INFO,
             "ls2k0300: const_timer calibration failed (measured=%llu), "
             "keeping default\n", (unsigned long long)measured);
    }

  return OK;
}

