/* Measure the constant timer's actual decrement rate by sampling CSR.TVAL
 * across a short stable-counter interval (drdtime).  TVAL decrements once
 * per constant-timer cycle, so (v0 - v1) over a known drdtime interval
 * gives the constant-timer frequency.
 */
static uint64_t measure_const_timer_rate(uint64_t stable_freq)
{
  uint64_t d0, d1;
  uint64_t v0, v1;
  uint64_t interval_ticks;  /* drdtime ticks for the sample window */
  uint64_t elapsed_d;
  int64_t  delta_v;

  /* Sample window: ~1ms of real time, in stable-counter ticks. */
  interval_ticks = stable_freq / 1000;   /* 1 ms */

  d0 = drdtime();
  v0 = csr_readq(LOONGARCH_CSR_TVAL);   /* current TVAL */

  do {
    d1 = drdtime();
  } while (d1 - d0 < interval_ticks);

  v1 = csr_readq(LOONGARCH_CSR_TVAL);

  elapsed_d = d1 - d0;
  /* TVAL counts DOWN. Over the window it decremented (v0 - v1), but in
   * periodic mode it may have reloaded (wrapped) — keep window short
   * enough that it does not wrap. */
  delta_v = (int64_t)(v0 - v1);
  if (delta_v <= 0)
    return 0;

  /* const_timer_freq = delta_v / (elapsed_d / stable_freq)
     = delta_v * stable_freq / elapsed_d */
  return delta_v * stable_freq / elapsed_d;
}
```

