/* Calibrate the stable-counter (rdtime) frequency by counting its ticks
 * during exactly one RTC second.
 *
 * NOTE: on the 2K0300 the stable counter and the constant timer
 * (CSR.TCFG) are NOT in the same clock domain, so this value cannot be
 * used directly to program the system tick.  It is used only as the time
 * reference for ls2k0300_measure_const_timer_rate() below, which samples
 * the constant timer's own decrement rate.
 *
 * This must run after the RTC oscillator has been enabled (i.e. after
 * ls2k0300_rtc_hw_init).
 *
 * Returns the measured stable-counter frequency in Hz, or 0 if the RTC
 * was not ticking.
 */
static uint64_t ls2k0300_measure_stable_freq(
    FAR struct ls2k0300_rtc_lowerhalf_s *priv)
{
  uint32_t toy;
  uint32_t prev;
  uint32_t now;
  uint32_t i;
  uint64_t t0;
  uint64_t t1;

  /* Snapshot the current RTC seconds field. */

  toy  = rtc_getreg(priv, LS2K0300_RTC_TOY_READ0_REG);
  prev = (toy >> RTC_TOY_SEC_SHIFT) & RTC_TOY_SEC_MASK;

  /* Wait for the seconds field to change once (catches a boundary). */

  for (i = 0; i < RTC_SEC_POLL_MAX; i++)
    {
      toy = rtc_getreg(priv, LS2K0300_RTC_TOY_READ0_REG);
      now = (toy >> RTC_TOY_SEC_SHIFT) & RTC_TOY_SEC_MASK;
      if (now != prev)
        {
          break;
        }
    }

  if (now == prev)
    {
      return 0;  /* RTC not ticking */
    }

  /* Measure stable-counter ticks across one full RTC second. */

  t0  = drdtime();
  prev = now;

  for (i = 0; i < RTC_SEC_POLL_MAX; i++)
    {
      toy = rtc_getreg(priv, LS2K0300_RTC_TOY_READ0_REG);
      now = (toy >> RTC_TOY_SEC_SHIFT) & RTC_TOY_SEC_MASK;
      if (now != prev)
        {
          break;
        }
    }

  t1 = drdtime();

  if (now == prev || t1 <= t0)
    {
      return 0;
    }

  return t1 - t0;
}

/* Measure the constant timer's (CSR.TCFG) actual decrement rate by sampling
 * CSR.TVAL across a short stable-counter window.
 *
 * The stable counter (rdtime) and the constant timer run at different rates
 * on the 2K0300, so the only reliable way to know how fast CSR.TVAL counts
 * down is to measure it.  TVAL counts down by one per constant-timer cycle;
 * sampling it over a known stable-counter interval yields the constant-
 * timer frequency:
 *
 *   const_freq = (TVAL_decrement) * stable_freq / (drdtime_delta)
 *
 * The window is kept well below one timer period (programmed to 10 ms by
 * up_timer_initialize(), i.e. ~25 ms at the true ~40 MHz rate) so that TVAL
 * does not wrap around during the sample.  Returns 0 on failure.
 */
static uint64_t ls2k0300_measure_const_timer_rate(uint64_t stable_freq)
{
  uint64_t window;
  uint64_t d0;
  uint64_t d1;
  uint64_t v0;
  uint64_t v1;
  uint64_t dd;
  int64_t  dv;

  if (stable_freq == 0)
    {
      return 0;
    }

  /* ~1 ms of real time, expressed in stable-counter ticks. */

  window = stable_freq / 1000;

  d0 = drdtime();
  v0 = csr_readq(LOONGARCH_CSR_TVAL);

  do
    {
      d1 = drdtime();
    }
  while (d1 - d0 < window);

  v1 = csr_readq(LOONGARCH_CSR_TVAL);

  dd = d1 - d0;
  dv = (int64_t)v0 - (int64_t)v1;   /* TVAL counts downward */
  if (dd == 0 || dv <= 0)
    {
      return 0;
    }

  return (uint64_t)dv * stable_freq / dd;
}

/* Reprogram the constant timer (CSR.TCFG) for the given frequency. */
static void ls2k0300_reprogram_const_timer(uint64_t freq)
{
  uint64_t tval;
  uint64_t tcfg;

  tval = freq / TICK_PER_SEC;
  tcfg  = tval << CSR_TCFG_VAL_SHIFT;
  tcfg |= CSR_TCFG_PERIOD | CSR_TCFG_EN;
  csr_writeq(tcfg, LOONGARCH_CSR_TCFG);
}

int ls2k0300_rtc_initialize(void)
{
  FAR struct rtc_lowerhalf_s *lower;
  uint64_t stable_freq;
  uint64_t ct_freq;
  int ret;

  ls2k0300_rtc_hw_init(&g_rtc_lowerhalf);

  lower = (FAR struct rtc_lowerhalf_s *)&g_rtc_lowerhalf;
  up_rtc_set_lowerhalf(lower, true);

  ret = rtc_initialize(0, lower);
  if (ret < 0)
    {
      rtcerr("ERROR: rtc_initialize failed: %d\n", ret);
      return ret;
    }

  /* Calibrate the constant timer against the RTC and reprogram CSR.TCFG.
   *
   * clock_initialize() calls up_rtc_initialize() (-> this function) after
   * up_timer_initialize() and before clock_inittime(), so the corrected
   * tick is in effect before the wall clock is seeded from the RTC, and
   * clock_inittime() self-corrects for whatever systicks accumulated
   * during calibration.  Only apply a measured value that is sane.
   *
   * Two steps are needed because, on the 2K0300, rdtime (stable counter)
   * and CSR.TCFG (constant timer) are clocked independently: first measure
   * the stable-counter rate using the RTC as the absolute reference, then
   * measure the constant timer's own decrement rate against the stable
   * counter.
   */

  stable_freq = ls2k0300_measure_stable_freq(&g_rtc_lowerhalf);
  if (stable_freq >= 1000000ULL && stable_freq <= 1000000000ULL)
    {
