                 (unsigned long long)(ct_freq / TICK_PER_SEC),
                 (unsigned long long)stable_freq);
        }
      else
        {
          syslog(LOG_INFO,
                 "ls2k0300: const_timer rate measurement failed "
                 "(ct_freq=%llu, stable=%llu), keeping default\n",
                 (unsigned long long)ct_freq,
                 (unsigned long long)stable_freq);
        }
    }
  else
    {
      syslog(LOG_INFO,
             "ls2k0300: stable-counter calibration failed "
             "(stable=%llu), keeping default\n",
             (unsigned long long)stable_freq);
    }

  return OK;
}
